/* A furnished home with useful rooms, growing beds and everyday county pursuits. */
(()=>{'use strict';
const rooms=[
{id:'cottageKitchen',name:'Your Kitchen',image:'cottage-kitchen',text:'Copper pans, a working stove, herbs, a bread board and a table for meals you make yourself.'},
{id:'cottageBath',name:'Your Bathroom',image:'cottage-bath',text:'A copper bath, washbasin, fresh towels and a quiet place to unwind.'},
{id:'cottageSitting',name:'Your Sitting Room',image:'cottage-sitting',text:'A furnished fireside room with comfortable chairs, books and a place for friends.'},
{id:'cottageDen',name:'Your Den',image:'cottage-den',text:'Your writing desk, yarn basket and craft table, with a journal that remembers your words.'},
{id:'cottageBasement',name:'Your Basement',image:'cottage-basement',text:'Shelves for preserves, old keepsakes, a repair bench and wooden stairs back upstairs.'},
{id:'cottagePorch',name:'Your Back Porch',image:'cottage-porch',outside:true,text:'Rocking chairs, hanging plants and a tea table overlooking your tulips and vegetable beds.'},
{id:'cottageYard',name:'Your Tulip Backyard & Garden',image:'cottage-yard',outside:true,text:'A colorful tulip border surrounds your raised vegetable beds. Plant, water, harvest and bring something home.'},
{id:'cottageBedroom',name:'Your Bedroom',image:'cottage-bedroom',text:'A patchwork quilt, wardrobe, bedside lamp and a peaceful place to rest and stitch.'}
];
const activities=[];
function A(id,room,title,text,choices,answer,effect={}){activities.push({id,room,district:'home',title,text,kind:Array.isArray(answer)?'sequence':'choice',choices,answer,hint:Array.isArray(answer)?'Follow the order described in the activity card.':'Look for the choice that fits the activity.',...effect})}
A('soup','cottageKitchen','Cook garden vegetable soup','Prepare vegetables → add broth → simmer gently.',['Simmer gently','Prepare vegetables','Add broth'],[1,2,0],{food:'garden soup',cook:true});
A('bread','cottageKitchen','Bake a cottage loaf','Mix → knead → prove → bake.',['Bake','Mix','Prove','Knead'],[1,3,2,0],{food:'cottage loaf',cook:true});
A('tea','cottageKitchen','Brew a pot of herbal tea','Choose mint, steep in hot water, then pour into your teapot.',['Pour tea','Choose mint','Steep in hot water'],[1,2,0],{food:'herbal tea',cook:true});
A('bath','cottageBath','Take a lavender bath','Make a comfortable bath: run warm water, add lavender, then settle in.',['Settle in','Run warm water','Add lavender'],[1,2,0],{comfort:'A lavender bath'});
A('laundry','cottageBath','Wash and fold the linens','Wash → rinse → dry → fold.',['Dry','Fold','Wash','Rinse'],[2,3,0,1],{project:'Fresh cottage linens'});
A('sachet','cottageBath','Make a lavender sachet','What belongs in a fragrant linen sachet?',['Dried lavender inside a sewn fabric pouch','A dripping wet towel','Loose soil'],0,{keepsake:'My handmade lavender sachet',craft:true});
A('fireside','cottageSitting','Settle by the fireplace','What makes your sitting room comfortable?',['A cushion, a warm drink and a favorite book','An uncomfortable empty stool','A pile of unopened chores'],0,{comfort:'A peaceful fireside hour'});
A('visit','cottageSitting','Invite Pip for afternoon tea','Brew herbal tea in your kitchen first. How will you welcome Pip?',['A seat, a shared teapot and time to listen','Hide the teapot','Ignore the knock'],0,{cost:'herbal tea',friend:'pip',keepsake:'Pip’s first sitting-room tea invitation'});
A('quilt','cottageSitting','Piece a patchwork cushion','Arrange → pin → stitch → press.',['Stitch','Arrange','Press','Pin'],[1,3,0,2],{project:'My patchwork sitting-room cushion',craft:true});
A('knit','cottageDen','Knit a woodland scarf','Repeat the pattern knit → knit → purl → knit.',['Purl','Knit'],[1,1,0,1],{keepsake:'My woodland knitted scarf',craft:true});
A('crochet','cottageDen','Crochet a tulip coaster','Chain → join the ring → work petals → weave in ends.',['Work petals','Chain','Weave in ends','Join the ring'],[1,3,0,2],{keepsake:'My crocheted tulip coaster',craft:true});
A('sketch','cottageDen','Sketch my garden design','Which plan leaves your vegetable beds easy to reach?',['Paths between the beds and tulips around the border','No paths at all','Beds behind a locked wall'],0,{project:'My cottage garden sketch'});
A('preserve','cottageBasement','Preserve my garden harvest','Harvest vegetables in your backyard first. Prepare → simmer → fill jars.',['Fill jars','Prepare vegetables','Simmer'],[1,2,0],{cost:'garden vegetables',food:'garden preserves',cook:true});
A('repair','cottageBasement','Restore the old workbench','Clean the bench → tighten its joints → sand it smooth.',['Sand smooth','Clean the bench','Tighten joints'],[1,2,0],{project:'Restored basement workbench',craft:true});
A('chest','cottageBasement','Sort the family keepsake chest','How should you preserve an old handwritten letter?',['Keep it dry in a protective folder','Leave it beside a leaking pipe','Scrub away the old ink'],0,{keepsake:'The cottage’s old handwritten letter'});
A('porchtea','cottagePorch','Rock on the porch with tea','Brew herbal tea in your kitchen first. Choose your favorite porch moment.',['Listen to birds beside the garden','Rush past without sitting','Spill the whole pot'],0,{cost:'herbal tea',comfort:'Tea on my back porch'});
A('birds','cottagePorch','Watch the garden birds','How can you watch a robin comfortably?',['Stay quiet and let it keep its space','Chase it from branch to branch','Shake its nest'],0,{keepsake:'My backyard robin observation'});
A('stars','cottagePorch','Trace the porch constellation','After real nightfall, follow Moon → Tulip → Star → Moon.',['Star','Moon','Tulip'],[1,2,0,1],{night:true,keepsake:'My porch constellation chart'});
A('tulipcare','cottageYard','Tend the tulip border','Which care helps the growing tulips?',['Water the soil gently and leave the roots in place','Pull up the whole border','Trample the beds'],0,{project:'A lovingly tended tulip border'});
A('compost','cottageYard','Turn the garden compost','Layer leaves → add vegetable scraps → turn the pile.',['Turn pile','Layer leaves','Add vegetable scraps'],[1,2,0],{project:'My thriving garden compost'});
A('bedtime','cottageBedroom','Rest under my patchwork quilt','Choose a peaceful rest. The real clock continues.',['Settle down and breathe slowly','Demand the calendar skip a day','Leave every lamp glaring'],0,{comfort:'A peaceful rest under my quilt'});
A('embroidery','cottageBedroom','Embroider a pillowcase','Thread needle → stitch the tulip → secure the thread.',['Secure thread','Thread needle','Stitch the tulip'],[1,2,0],{project:'My embroidered tulip pillowcase',craft:true});
A('wardrobe','cottageBedroom','Mend my favorite cardigan','Find the loose seam → pin the edges → stitch → finish.',['Finish','Pin the edges','Find loose seam','Stitch'],[2,1,3,0],{project:'My lovingly mended cardigan',craft:true});
const local=[
['capital','lanterncare','Help tend the street lanterns','Clean glass → check the wick → light the lantern.',['Light lantern','Clean glass','Check wick'],[1,2,0],'Lantern keeper’s ribbon'],
['market','basket','Pack the picnic basket','Four friends need one bun each. How many buns?',['Two','Four','Eight'],1,'Market picnic recipe'],
['home','welcome','Make a neighborhood welcome card','Which welcome makes room for a new neighbor?',['Your name, a kind note and an invitation','A list of demands','An empty envelope'],0,'My Willowwood welcome card'],
['gardens','pollinators','Plan a pollinator corner','What welcomes butterflies?',['Flowering plants and an undisturbed sunny corner','Remove every flower','Pave every bed'],0,'Butterfly garden field note'],
['festival','garland','Weave a festival lantern garland','Measure cord → attach lanterns → hang the garland.',['Hang garland','Measure cord','Attach lanterns'],[1,2,0],'My festival garland'],
['workshop','leathermend','Mend a traveler’s satchel','Inspect seam → mark stitches → sew → finish.',['Sew','Finish','Inspect seam','Mark stitches'],[2,3,0,1],'Satchel mender’s token'],
['academy','herbarium','Prepare a moonlight herbarium','How do you keep a plant specimen with its identity?',['Press a fallen leaf and label where you found it','Remove every plant','Store it soaking wet'],0,'My moonlight herbarium page'],
['forest','trail','Restore a woodland trail marker','Read the trail map → check the junction → replace the marker.',['Replace marker','Read trail map','Check junction'],[1,2,0],'Woodland trail keeper’s badge'],
['forgotten','restore','Restore a forgotten mosaic','Record its pattern → clean gently → fit loose pieces.',['Fit loose pieces','Record pattern','Clean gently'],[1,2,0],'A sketch of the restored mosaic'],
['court','community','Plan a county gathering','How do you make the gathering welcoming?',['Music, seating, clear paths and a quieter corner','Only one standing place','Block every doorway'],0,'County gathering planner’s seal'],
['library','bookbind','Bind a little storybook','Order pages → fold → stitch → add cover.',['Add cover','Order pages','Stitch','Fold'],[1,3,2,0],'My handbound storybook']
];
for(const [district,id,title,text,choices,answer,keepsake]of local){A('local_'+id,null,title,text,choices,answer,{district,keepsake,craft:['leathermend','bookbind','garland'].includes(id)})}
function record(x){return x&&typeof x==='object'&&!Array.isArray(x)}
function ensure(s){if(!record(s.cityCottage))s.cityCottage={};const q=s.cityCottage;for(const k of ['completed','projects','bag','comfort','patches'])if(!record(q[k]))q[k]={};if(typeof q.journal!=='string')q.journal='';return q}
function at(a,w){return !!a&&w?.district===a.district&&w.room===a.room&&!w.porch}
function available(s,a,w,c){if(!at(a,w))return'Visit this activity’s location first.';if(a.night&&!c.night)return'The porch stars appear after real nightfall. A lighting preview leaves the actual clock unchanged.';if(a.cost&&!(ensure(s).bag[a.cost]>0))return'You need '+a.cost+' first. Make tea in the kitchen or harvest vegetables in your backyard.';return''}
function finish(s,id,response,w,c){const a=activities.find(a=>a.id===id);if(!a)return{ok:false,reason:'Choose an activity.'};const q=ensure(s);if(!at(a,w))return{ok:false,reason:'Visit this activity’s location first.'};if(q.completed[c.key+':'+id])return{ok:true,title:a.title+' · a peaceful practice',detail:'You already received today’s reward. Your supplies have not been used again.'};const reason=available(s,a,w,c);if(reason)return{ok:false,reason};const answer=globalThis.EldoriaPromiseModel?.guide(s,a,response)??response;const correct=Array.isArray(a.answer)?Array.isArray(answer)&&answer.length===a.answer.length&&answer.every((v,i)=>v===a.answer[i]):answer===a.answer;if(!correct)return{ok:false,reason:a.hint};const key=c.key+':'+id;if(q.completed[key])return{ok:true,title:a.title+' · a peaceful practice',detail:'You already received today’s reward. Your supplies have not been used again.'};q.completed[key]=true;if(a.cost)q.bag[a.cost]--;if(a.food)q.bag[a.food]=(q.bag[a.food]||0)+(a.food==='herbal tea'?3:1);if(a.project)q.projects[a.project]=true;if(a.comfort)q.comfort[a.comfort]=true;const L=globalThis.EldoriaLifeModel,l=L.ensure(s);if(a.keepsake&&!l.collection.includes(a.keepsake))l.collection.push(a.keepsake);if(a.friend)l.friends[a.friend]=(l.friends[a.friend]||0)+2;if(a.cook)s.cookedMeals=(s.cookedMeals||0)+1;if(a.craft)q.made=(q.made||0)+1;if(globalThis.EldoriaPromiseModel?.active(s,c)&&!a.cook)globalThis.EldoriaPromiseModel.record(s,'Perfect midnight work: '+a.title,a.craft?'craft':'home','Made in my Willowwood cottage',c);l.xp+=3;s.coins=(s.coins||0)+5;const detail=a.food?'A serving of '+a.food+' is in your cottage pantry. Eat it or share it from the kitchen.':a.project?'Your finished project is saved and displayed in this room.':a.keepsake?'Your keepsake is saved in your collection and can be displayed in your legacy room.':a.friend?'Your guest remembers your welcome. Pip’s friendship grows by two.':'This comfortable moment is saved in your home journal.';return{ok:true,title:a.title+' · complete',detail,coins:5}}
function plant(s,kind,w,c,now=Date.now()){if(w?.district!=='home'||w.room!=='cottageYard'||!['tulips','vegetables'].includes(kind))return{ok:false,reason:'Visit your backyard garden first.'};const q=ensure(s);if(q.patches[kind])return{ok:false,reason:'This bed is already planted. Harvest it when it is ready.'};if(q.completed[c.key+':harvest:'+kind])return{ok:false,reason:'This bed has given today’s harvest. Plant again after real midnight.'};q.patches[kind]={readyAt:now+60000};return{ok:true,title:kind==='tulips'?'A fresh tulip cutting bed planted':'My vegetable bed planted',detail:'Your watered bed grows for one real minute, including while you explore or are away. The established tulip border stays in bloom.'}}
function harvest(s,kind,w,c,now=Date.now()){if(w?.district!=='home'||w.room!=='cottageYard'||!['tulips','vegetables'].includes(kind))return{ok:false,reason:'Visit your backyard garden first.'};const q=ensure(s),p=q.patches[kind];if(!p)return{ok:false,reason:'Plant this bed first.'};if(now<p.readyAt)return{ok:false,reason:'Your watered bed is still growing. Return in '+Math.ceil((p.readyAt-now)/1000)+' seconds.'};const key=c.key+':harvest:'+kind;if(q.completed[key])return{ok:false,reason:'You already gathered today’s harvest from this bed.'};delete q.patches[kind];q.completed[key]=true;if(kind==='tulips'){const l=globalThis.EldoriaLifeModel.ensure(s);l.bag.flowers=(l.bag.flowers||0)+3;if(!l.collection.includes('Tulips from my own backyard'))l.collection.push('Tulips from my own backyard')}else q.bag['garden vegetables']=(q.bag['garden vegetables']||0)+2;s.gardensTended=(s.gardensTended||0)+1;return{ok:true,title:kind==='tulips'?'Three tulips gathered for neighbor bouquets':'Two baskets of garden vegetables harvested',detail:kind==='tulips'?'Your flowers are available for bouquets when you visit your neighbors.':'Bring your vegetables to the basement preserving table.'}}
function serve(s,item,share,w){if(w?.district!=='home'||!['cottageKitchen','cottageSitting','cottagePorch'].includes(w.room))return{ok:false,reason:'Serve food in your kitchen, sitting room or back porch.'};const q=ensure(s);if(!['garden soup','cottage loaf','herbal tea','garden preserves'].includes(item)||!(q.bag[item]>0))return{ok:false,reason:'There is no serving of that in your pantry.'};q.bag[item]--;s.mealsEnjoyed=(s.mealsEnjoyed||0)+1;if(share){const l=globalThis.EldoriaLifeModel.ensure(s);l.friends.fern=(l.friends.fern||0)+1}return{ok:true,title:share?item+' shared with Fern':item+' enjoyed at home',detail:share?'Fern remembers your kindness. Your friendship grows by one.':'A homemade serving enjoyed. The remaining pantry is saved.'}}
function write(s,text,w){if(w?.district!=='home'||w.room!=='cottageDen')return false;ensure(s).journal=String(text).slice(0,2000);return true}
globalThis.EldoriaCottageModel={rooms,activities,ensure,at,available,finish,plant,harvest,serve,write};
})();
